#!/usr/bin/env python3
"""
Round 140b (culprits), 2 October 2026. Needs round 139b.

Combine the ticked layers: works in any order; areas and pictures faded outside where the layers meet.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 140b (2 October)\n\nNeeds round 139b. No tiles patch. No app.js?v= bump.\n\n- Combine the ticked layers (asked 2 October: it did not work on the map;\n  only the overlapping parts should show, the rest deleted or faded out, and\n  the choice should not depend on being made before or after the ticks):\n  - every tick or untick re-runs it (hook at the end of applyVisibility), and\n    when the map is idle comboSig compares the rows showing with what the\n    combine was made from, so rows whose layers are made late (lazy rows)\n    join too; rows with nothing read yet are tried again up to six times;\n  - pictures (shaded maps) now take part, counted where they paint, read from\n    their zoom-2 squares (comboPictureGrid, cached per picture address);\n  - areas and pictures cannot be cut along an edge, so outside the meeting\n    places they are faded by a dark veil (layer combo-mask, #050A12 at 0.82,\n    kept out of the colour mapping), the world less the kept squares, laid\n    just above the highest picture or area taking part (else just below the\n    lowest row taking part); points and lines are still cut with "within";\n  - rowFeatures reads a row\'s GeoJSON once per address (rowJson) and through\n    the map\'s own protocols (fetch alone failed on own:// style addresses).\n- Checked in Chromium (MapLibre 5.24, globe): the within cut keeps only the\n  points inside, the veil covers the rest of an area. The whole map was not\n  run in a browser.\n']


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round140b: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 139b" not in h.read_text(encoding="utf-8"):
        sys.exit("round140b: round 139b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round140b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", "map/index.html", check=False)
            sys.exit("round140b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round140b: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


DIFF = ""

if __name__ == "__main__":
    main()
